import java.util.*;

public class Ex02SpiLoading {
    interface AutoConfiguration { String name(); }

    public static class WebAutoConfig implements AutoConfiguration {
        public String name() { return "WebMvcAutoConfiguration"; }
    }
    public static class DataSourceAutoConfig implements AutoConfiguration {
        public String name() { return "DataSourceAutoConfiguration"; }
    }

    // 等价的 META-INF/spring/...AutoConfiguration.imports 内容（每行一个全限定类名）
    static List<String> readImports() {
        return Arrays.asList(
                "Ex02SpiLoading$WebAutoConfig",
                "Ex02SpiLoading$DataSourceAutoConfig",
                "Ex02SpiLoading$MissingAutoConfig");
    }

    public static void main(String[] args) throws Exception {
        List<String> lines = readImports();
        System.out.println("imports lines = " + lines.size());
        int loaded = 0;
        for (String fqcn : lines) {
            try {
                Class<?> c = Class.forName(fqcn);
                var ctor = c.getDeclaredConstructor();
                ctor.setAccessible(true);
                AutoConfiguration cfg = (AutoConfiguration) ctor.newInstance();
                System.out.println("  loaded: " + cfg.name());
                loaded++;
            } catch (ClassNotFoundException e) {
                // Spring 同样会吞掉这个异常并记入失败分析报告
                System.out.println("  ClassNotFound (skipped): " + fqcn);
            }
        }
        System.out.println("loaded = " + loaded + " / " + lines.size());
    }
}
